#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';
import { args, sha256, inside, walk, readJSON } from './lib.mjs';

export async function generateOffline(configFile, check = false) {
  const config = await readJSON(configFile), root = path.dirname(path.resolve(configFile));
  if (typeof config.prefix !== 'string' || !/^[\w.-]+$/.test(config.prefix)) throw new Error('A cache prefix is required.');
  const metadata = config.metadata ?? {};
  if (typeof metadata !== 'object' || Array.isArray(metadata) || ['prefix', 'version', 'assets', 'hashes', 'cdnFallbacks'].some(key => Object.hasOwn(metadata, key))) throw new Error('Offline metadata cannot override manifest fields.');
  const assets = new Set();
  for (const entry of config.files) {
    const file = inside(root, entry), stat = await fs.lstat(file);
    if (stat.isSymbolicLink()) throw new Error('Offline files cannot be symlinks.');
    for (const name of stat.isDirectory() ? await walk(root, entry) : [entry]) assets.add(name);
  }
  const hashes = {};
  for (const file of [...assets].sort()) hashes[file] = sha256(await fs.readFile(inside(root, file)));
  for (const [url, hash] of Object.entries(config.remote ?? {})) {
    if (!url.startsWith('https://') || !/^[a-f0-9]{64}$/.test(hash)) throw new Error('Remote assets need HTTPS and a SHA-256 pin.');
    assets.add(url); hashes[url] = hash;
  }
  const version = config.prefix + '-' + sha256(JSON.stringify({ hashes, cdnFallbacks: config.cdnFallbacks ?? {}, ...(Object.keys(metadata).length ? {metadata} : {}) })).slice(0, 16);
  const manifest = { ...metadata, prefix: config.prefix, version, assets: [...assets].sort(), hashes, cdnFallbacks: config.cdnFallbacks ?? {} };
  const output = inside(root, config.output ?? 'offline-assets.js');
  if (assets.has(config.output ?? 'offline-assets.js')) throw new Error('Manifest cannot hash itself.');
  const source = '// Generated by fragment-kit tools/offline-assets.mjs.\n(function (self) { self.OfflineAssets = ' + JSON.stringify(manifest, null, 2) + ';\nif (typeof module !== "undefined") module.exports = self.OfflineAssets; })(globalThis);\n';
  if (check) { if (await fs.readFile(output, 'utf8') !== source) throw new Error('Offline asset manifest is stale.'); }
  else await fs.writeFile(output, source);
  return manifest;
}
if (process.argv[1] && path.resolve(process.argv[1]) === new URL(import.meta.url).pathname) {
  const options = args();
  generateOffline(options.config ?? 'offline.config.json', Boolean(options.check)).then(value => console.log(value.version)).catch(error => { console.error(error.message); process.exitCode = 1; });
}
